<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { request } from '../api/http'
import { listManuscripts, stateLabel, type Manuscript } from '../api/manuscripts'
const items = ref<Manuscript[]>([]), page = ref(1), total = ref(0), q = ref(''), status = ref(''), loading = ref(false), error = ref('')
let requestId = 0
async function load(reset = false) { if (reset) page.value = 1; const current = ++requestId; loading.value = true; error.value = ''; try { const result = await listManuscripts(page.value, q.value, status.value); if (current === requestId) { items.value = result.items; total.value = result.total } } catch (failure) { if (current === requestId) error.value = failure instanceof Error ? failure.message : '读取失败' } finally { if (current === requestId) loading.value = false } }
async function remove(item: Manuscript) { try { await ElMessageBox.confirm(`确认删除草稿“${item.title || '未命名'}”？`, '删除草稿', { confirmButtonText: '删除', cancelButtonText: '取消', type: 'warning' }) } catch { return }; try { await request(`/api/manuscripts/${item.manuscriptId}`, { method: 'DELETE' }); await load() } catch (failure) { error.value = failure instanceof Error ? failure.message : '删除失败' } }
onMounted(() => load())
</script>
<template><div class="panel"><div class="list-filters"><el-input v-model="q" aria-label="搜索稿件标题" placeholder="搜索稿件标题" clearable @keyup.enter="load(true)" /><el-select v-model="status" aria-label="稿件状态" placeholder="全部状态" clearable @change="load(true)"><el-option v-for="key in ['DRAFT','PENDING','RETURNED','APPROVED','REJECTED']" :key="key" :label="stateLabel[key]" :value="key" /></el-select><el-button @click="load(true)">查询</el-button><RouterLink to="/manuscripts/new"><el-button type="primary">新建稿件</el-button></RouterLink></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table v-loading="loading" :data="items" empty-text="暂无组织稿件"><el-table-column prop="title" label="标题" min-width="220"><template #default="{row}">{{ row.title || '未命名草稿' }}</template></el-table-column><el-table-column prop="organizationName" label="组织" width="160" /><el-table-column label="状态" width="90"><template #default="{row}"><el-tag effect="plain">{{ stateLabel[row.status] }}</el-tag></template></el-table-column><el-table-column label="最近更新" width="180"><template #default="{row}">{{ new Date(row.updatedAt).toLocaleString('zh-CN') }}</template></el-table-column><el-table-column label="操作" min-width="210"><template #default="{row}"><div class="row-actions"><RouterLink v-if="['DRAFT','RETURNED'].includes(row.status)" :to="`/manuscripts/${row.manuscriptId}/edit`">{{ row.status === 'RETURNED' ? '修改重提' : '编辑' }}</RouterLink><RouterLink v-if="row.currentSubmissionId" :to="`/manuscripts/${row.manuscriptId}/history`">版本与状态</RouterLink><RouterLink v-if="row.publicationState === 'PUBLISHED'" :to="`/publications/${row.manuscriptId}`">发布内容</RouterLink><el-button v-if="row.status === 'DRAFT'" link type="danger" @click="remove(row)">删除草稿</el-button></div></template></el-table-column></el-table><el-pagination v-if="total > 20" v-model:current-page="page" layout="prev, pager, next, total" :page-size="20" :total="total" @current-change="load()" /></div></template>
